  transforms:
    - command: update
      reason: rename
      args: { target: '$.paths["/users"].post', value: { summary: hi } }
    - command: update
      reason: template
      args: { target: '$.components.schemas.U.properties.id.type', value: '[{{value}}]', template: true }
    - command: append
      reason: add
      args: { target: '$.components.schemas.Page.properties', value: { total: { type: integer } } }
    - command: merge
      reason: merge
      args: { target: '$..parameters[?(@.name == "after")]', value: { schema: { format: uuid } } }
    - command: remove
      reason: drop
      args: { target: '$.components.securitySchemes.Broken' }
    - command: copy
      reason: copy
      args: { from: '$.components.schemas.U', to: ['$.components.schemas.V', '$.components.schemas.U.properties.self'] }
    - command: move
      reason: move
      args: { from: '$.components.schemas.V', to: '$.components.schemas.W' }
    - command: remove
      reason: missing
      args: { target: '$.nope' }
    - command: update
      args: { target: '$.info[', value: 1 }
    - { command: oneOfToAnyOf, reason: legacy }
    - command: update
      reason: matches
      args: { target: [{ matches_schema: '$.components.schemas.U', ignore: '$.components.schemas.U' }], value: { $ref: '#/components/schemas/U' } }
