  Bearer: { type: http, scheme: bearer }
query_settings: { nested_format: dots, array_format: indices }
streaming:
  on_event:
    - { data_starts_with: '[DONE]', handle: done }
    - { event_type: error, handle: error, error_property: message }
pagination:
  - name: cursor_page
    type: cursor
    request:
      after: { type: string, x-stainless-pagination-property: { purpose: next_cursor_param } }
      limit: { type: integer }
    response:
      data: { type: array, x-stainless-pagination-property: { purpose: items } }
      next_cursor: { type: string, x-stainless-pagination-property: { purpose: next_cursor_field } }
resources:
  $shared:
    models: { page: Page }
  users:
    models: { user: U, loop: Loop, ghost: Ghost }
    methods:
      list: get /users
      create: { endpoint: post /users, streaming: { param_discriminator: stream, stream_event_model: users.user } }
      retrieve: { endpoint: 'get /users/{id}', paginated: cursor_page }
      bad: { endpoint: 'get /users/{id}', paginated: nope }
      alias: get /aliased
      stream: { endpoint: get /stream, streaming: { stream_event_model: users.nope } }
    subresources:
      posts:
        methods:
          list_posts: { endpoint: GET /users, paginated: true }
  $client:
    methods:
      ping: get /users/{id}
